{
  "core_question": "What clinical, legal, and financial analyses must the board conduct to evaluate a private-equity acquisition that converts a rural nonprofit hospital to for-profit, spins out a charitable foundation, and uses a sale‑leaseback of real estate?",
  "rationale": "The scenario involves medical operations, regulatory compliance for nonprofit conversion and sale‑leaseback, and complex financial structuring with tax implications.",
  "routes": ["healthcare", "legal", "finance"],
  "sub_questions": {
    "healthcare": "What clinical impact assessments should the board perform to ensure that converting the hospital from a nonprofit to a for-profit entity will not compromise patient care quality, staffing levels, or service availability in this rural community?",
    "legal": "What are the key legal and regulatory requirements—including IRS 501(c)(3) rules, state hospital licensing, sale‑leaseback tax treatment, and charitable foundation governance—that the board must review to ensure compliance with nonprofit conversion, real estate transaction, and foundation holding of proceeds?",
    "finance": "How should the board evaluate the financial feasibility of the private-equity acquisition, including the valuation of the operating entity, the sale‑leaseback structure, debt financing terms, projected cash flows, tax implications for the hospital and the charitable foundation, and potential impact on community benefit obligations?"
  },
  "requires_recency_disclosure": true,
  "recency_notes": "IRS guidance on nonprofit conversion and sale‑leaseback tax treatment; recent state licensing updates for rural hospitals; current market rates for real estate leaseback financing."
}
